import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    coop_rate = sum(1 for x in opp if x == 'C') / n
    my_coop_rate = sum(1 for x in me if x == 'C') / n

    def opp_defects_last_k(k):
        if n < k:
            return None
        return all(opp[-i] == 'D' for i in range(1, k + 1))

    def opp_coops_last_k(k):
        if n < k:
            return None
        return all(opp[-i] == 'C' for i in range(1, k + 1))

    if n < 10:
        if last_opp == 'D':
            if rng.random() < 0.55:
                return 'D'
        return 'C'

    recent_window = min(12, n)
    recent_opp = opp[-recent_window:]
    recent_coop = sum(1 for x in recent_opp if x == 'C') / recent_window

    long_window = min(40, n)
    long_opp = opp[-long_window:]
    long_coop = sum(1 for x in long_opp if x == 'C') / long_window

    if n >= 20:
        if long_coop < 0.15:
            return 'D'
        if long_coop < 0.35:
            if rng.random() < 0.75:
                return 'D'
            return 'C'

    if last_opp == 'D' and last_me == 'C':
        if rng.random() < 0.85:
            return 'D'

    if last_opp == 'D' and last_me == 'D':
        if recent_coop > 0.5 and rng.random() < 0.35:
            return 'C'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    d5 = opp_defects_last_k(5)
    if d5 is True:
        if recent_coop < 0.3:
            return 'D'
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    c8 = opp_coops_last_k(8)
    if c8 is True:
        return 'C'

    if recent_coop > 0.85 and long_coop > 0.7:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    if recent_coop > 0.6:
        if rng.random() < 0.9:
            return 'C'
        return 'D'

    if recent_coop > 0.4:
        if rng.random() < 0.65:
            return 'C'
        return 'D'

    if rng.random() < 0.35:
        return 'C'
    return 'D'
